package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTlDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Kanlungan mula sa Kasamaan ng Aking Mga Gawa", "O Allah, ako ay nagpapakupkop sa Iyo mula sa kasamaan ng aking nagawa at mula sa kasamaan ng hindi ko nagawa.", "Isang dua ng Propeta ﷺ, ayon kay Aisha (RA).", "Proteksyon mula sa mga kahihinatnan ng parehong ginawa at kung ano ang hindi nagawa."),
        "dua_jahdil_bala" to DuaText("Kanlungan mula sa Matinding Pagsubok", "O Allah, ako ay nagpapakupkop sa Iyo mula sa matinding pagsubok, mula sa maabutan ng paghihirap, mula sa isang masamang kautusan at mula sa pagmamapuri ng mga kaaway.", "Kanlungan mula sa matitinding pagsubok at ang pagmamalaki ng mga kaaway.", "Ang Propeta ﷺ ay humingi ng kanlungan mula sa apat na bagay na ito."),
        "dua_fitnat_ghina_faqr" to DuaText("Kanlungan mula sa mga Pagsubok ng Kayamanan at Kahirapan", "O Allah, ako ay nagpapakupkop sa Iyo mula sa katamaran at katandaan, mula sa kasalanan at utang, mula sa pagsubok at parusa sa libingan, mula sa pagsubok at parusa ng Apoy, mula sa kasamaan ng pagsubok ng kayamanan, at mula sa pagsubok ng kahirapan.", "Kanlungan mula sa mga pagsubok sa libingan, Impiyerno, kayamanan at kahirapan (bahagi ng dua).", "Isang komprehensibong dasal ng kanlungan mula sa Propeta ﷺ."),
        "dua_kufr_faqr" to DuaText("Kanlungan mula sa Kawalang-paniwala at Kahirapan", "O Allah, ako ay nagpapakupkop sa Iyo mula sa kawalan ng pananampalataya at kahirapan, at ako ay nagpapakupkop sa Iyo mula sa kaparusahan ng libingan. Walang diyos maliban sa Iyo.", "Tatlong beses umaga at gabi.", "Narinig ni Abu Bakrah (RA) ang Propeta ﷺ na nagsabi nito."),
        "dua_sharri_sami" to DuaText("Kanlungan mula sa Kasamaan ng Aking Pandama", "O Allah, ako ay nagpapakupkop sa Iyo mula sa kasamaan ng aking pandinig, sa kasamaan ng aking paningin, sa kasamaan ng aking dila, sa kasamaan ng aking puso at sa kasamaan ng aking pagnanasa.", "Itinuro kay Shakal ibn Humayd (RA).", "Isang dua upang protektahan ang mga paa at ang sarili mula sa kasalanan."),
        "dua_hadm_gharaq" to DuaText("Kanlungan mula sa Biglaang Kamatayan at Aksidente", "O Allah, ako ay nagpapakupkop sa Iyo mula sa pagkadurog (ng isang gusali), mula sa pagkahulog mula sa taas, mula sa pagkalunod, pagkasunog at katandaan; mula sa Shaytan na iniligaw ako sa oras ng kamatayan, mula sa pagkamatay habang tumatakas mula sa Iyong landas, at mula sa pagkamatay ng isang (makamandag) na tibo.", "Kanlungan mula sa mga aksidente at isang masamang kamatayan.", "Isang dua ng kanlungan mula sa Propeta ﷺ."),
        "dua_ju_khiyanah" to DuaText("Kanlungan mula sa Gutom at Pagkakanulo", "O Allah, ako ay nagpapakupkop sa Iyo mula sa gutom, sapagkat ito ay isang masamang kasama, at ako ay nagpapakupkop sa Iyo mula sa pagkakanulo, sapagkat ito ay isang masamang tiwala.", "Kanlungan mula sa gutom at pagkakanulo.", "Isang dua ng kanlungan mula sa Propeta ﷺ."),
        "dua_huda_tuqa" to DuaText("Patnubay, Kabanalan, Kalinisang-puri at Kasapatan", "O Allah, humihingi ako sa Iyo ng patnubay, kabanalan, kalinisang-puri at kasiyahan sa sarili.", "Isang maikli, komprehensibong panalangin ng Propeta ﷺ.", "Apat na pangunahing pagpapala ng relihiyon at ng mundong ito."),
        "dua_aslih_li_dini" to DuaText("Ituwid ang Aking Relihiyon, Mundo at Kabilang Buhay", "O Allah, ituwid mo ang aking relihiyon, na siyang pananggalang sa lahat ng aking mga gawain; ituwid ang aking makamundong buhay, kung saan ang aking kabuhayan; at ituwid ang aking Kabilang Buhay, na aking babalikan. Gawin mo ang buhay na dagdagan para sa akin sa bawat kabutihan, at gawin mo ang kamatayan na kaginhawahan para sa akin mula sa bawat kasamaan.", "Repormasyon sa relihiyon, sa mundong ito at sa Kabilang-Buhay - lahat ng tatlo.", "Isang komprehensibong dua ng Propeta ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Ibaling ang Aming Puso sa Iyong Pagsunod", "O Allah, Tagapagbalik ng mga puso, ibalik mo ang aming mga puso sa Iyong pagsunod.", "Isang panalangin upang panatilihing matatag ang puso sa pagsunod.", "Ang puso ng lahat ng tao ay nasa pagitan ng dalawang daliri ng Pinakamaawain."),
        "dua_jannah_nar" to DuaText("Humihingi ng Jannah, Kanlungan sa Apoy", "O Allah, humihingi ako sa Iyo ng Paraiso at nagpapakupkop ako sa Iyo mula sa Apoy.", "Pagkatapos ng tashahhud o anumang oras.", "Ang Propeta ﷺ ay nagsabi: ang ating mga duas ay umiikot din dito."),
        "dua_khayri_kullih" to DuaText("Lahat Mabuti, Ngayon at Mamaya", "O Allah, hinihiling ko sa Iyo ang lahat ng kabutihan — ang kaagad at ang naantala, ang nalalaman ko at ang hindi ko nalalaman — at nagpapakupkop ako sa Iyo mula sa lahat ng kasamaan — ang kaagad at ang naantala, ang nalalaman ko at hindi ko nalalaman. O Allah, humihingi ako sa Iyo ng Paraiso at sa anumang salita at gawa na naglalapit sa akin dito, at nagpapakupkop ako sa Iyo mula sa Apoy at sa anumang salita at gawa na maglalapit sa akin dito.", "Itinuro ng Propeta ﷺ ang komprehensibong dua na ito kay Aisha (RA) (bahagi ng dua).", "Isang dua na nagtitipon ng bawat kabutihan."),
        "dua_ihdini_saddidni" to DuaText("Gabayan at Panatilihing Matuwid", "O Allah, gabayan mo ako at panatilihin mo ako sa tamang landas.", "Itinuro ito ng Propeta ﷺ kay Ali (RA).", "Isipin ang patnubay bilang ginagabayan sa isang daan, at ang sadad bilang tuwid ng isang palaso."),
        "dua_hubbaka" to DuaText("Humihingi ng Pagmamahal sa Allah", "O Allah, hinihiling ko sa Iyo ang Iyong pag-ibig, ang pag-ibig ng mga nagmamahal sa Iyo, at ang mga gawa na naghahatid sa akin sa Iyong pag-ibig. O Allah, gawin Mong mas mahal sa akin ang Iyong pagmamahal kaysa sa aking sarili, sa aking pamilya at sa malamig na tubig.", "Ang dua ni Dawud (AS) na isinalaysay ng Propeta ﷺ.", "Ang pag-ibig sa Allah ay ang pinakadakilang kayamanan."),
        "dua_filal_khayrat" to DuaText("Paggawa ng Mabuti at Pag-iwan sa Kasamaan", "O Allah, hinihiling ko sa Iyo na bigyan Mo ako ng kakayahang gumawa ng mabuti, iwanan ang masasamang gawain at mahalin ang mahihirap, at patawarin Mo ako at maawa sa akin. At kapag ikaw ay nagnanais ng pagsubok para sa isang tao, kunin mo ako nang hindi sinusubok. Hinihiling ko sa Iyo ang Iyong pag-ibig, ang pag-ibig ng mga nagmamahal sa Iyo, at ang pag-ibig sa mga gawa na naglalapit sa akin sa Iyong pag-ibig.", "Itinuro ng Allah ang dua na ito sa Propeta ﷺ sa isang panaginip.", "Ang Propeta ﷺ ay nagsabi: ito ay totoo, kaya pag-aralan ito at ituro ito."),
        "dua_bi_ilmikal_ghayb" to DuaText("Hayaan Mo Akong Mabuhay Habang Maganda ang Buhay", "O Allah, sa pamamagitan ng Iyong kaalaman sa di-nakikita at ang Iyong kapangyarihan sa nilikha - buhayin Mo ako hangga't alam Mong ang buhay ay mas mabuti para sa akin, at kunin Mo ako kapag alam Mong ang kamatayan ay mas mabuti para sa akin. O Allah, hinihiling ko sa Iyo ang pagkatakot sa Iyo sa pribado at sa publiko, para sa salita ng katotohanan sa kasiyahan at galit, at para sa katamtaman sa kahirapan at sa kayamanan.", "Ang panalangin dua ni Ammar ibn Yasir (RA) (pambungad na bahagi).", "Ginawa ng Propeta ﷺ ang dua sa panalangin."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "O Allah, hinihiling ko sa Iyo, sapagka't sa Iyo ang lahat ng papuri; walang diyos maliban sa Iyo, ang Tagapagbigay ng mga biyaya, Tagapaglikha ng mga langit at lupa. O Nagmamay-ari ng Kamahalan at Karangalan, O Walang-hanggang Buhay, O Tagapagtaguyod!", "Ang Propeta ﷺ ay nagsabi na ang taong ito ay nagdasal gamit ang Pinakadakilang Pangalan ng Allah.", "Sinasagot ang isang dua na ginawa gamit ang Pangalan na ito."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "O Allah, hinihiling ko sa Iyo, sapagkat ako ay sumasaksi na Ikaw ay si Allah; walang diyos maliban sa Iyo, ang Nag-iisa, ang Makasarili, na hindi nagkaanak o ipinanganak, at walang maihahambing sa Kanya.", "Sinabi ng Propeta ﷺ na ang taong ito ay nagtanong kay Allah sa Kanyang Pinakadakilang Pangalan.", "Kapag hiningi nito, Siya ay nagbibigay; kapag tinawag nito, Siya ay sumasagot."),
        "dua_thabbitni_hadiyan" to DuaText("Gawin Mo akong Matatag, Patnubayan at Gabay", "O Allah, gawin mo akong matatag, at gawin mo akong isa na gumagabay at ginagabayan.", "Ginawa ng Propeta ﷺ ang dua para kay Jarir (RA) (para sa iyong sarili sabihin ang 'thabbitni').", "Ang orihinal na dua para sa Jarir (RA) ay gumagamit ng mga salitang 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Patawarin Mo Ako at Tanggapin ang Aking Pagsisisi", "Panginoon, patawarin mo ako at tanggapin mo ang aking pagsisisi. Katotohanan, Ikaw ang Tagatanggap ng pagsisisi, ang Maawain.", "Isang daang beses sa isang pag-upo — ang pagsasagawa ng Propeta ﷺ.", "Binilang ng mga Kasamahan ang Propeta ﷺ na sinasabi ito ng isang daang beses sa isang upuan."),
        "dua_rafiq_ala" to DuaText("Dua ng Namamatay na Tao", "O Allah, patawarin mo ako, maawa ka sa akin at isama mo ako sa Pinakamataas na Kasamahan.", "Ang huling dua ng Propeta ﷺ — para sa taong may sakit na sabihin para sa kanyang sarili.", "Ginawa ng Propeta ﷺ ang dua na ito sa oras ng kanyang pagpanaw."),
        "dua_la_bas_tahur" to DuaText("Pag-aliw sa Maysakit: Paglilinis", "Walang pinsala; ito ay isang paglilinis (mula sa mga kasalanan), kung niloob ng Allah.", "Upang aliwin ang maysakit kapag bumibisita.", "Sinabi ito ng Propeta ﷺ nang bumisita sa maysakit."),
        "dua_talqeen" to DuaText("Talqeen para sa Namamatay", "Walang sinumang karapat-dapat sambahin maliban kay Allah.", "Bigkasin ang kalimah malapit sa isang taong namamatay (huwag pilitin silang sabihin ito).", "Ang sinumang huling salita ay 'La ilaha illallah' ay papasok sa Paraiso (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Sa halip na Maghangad ng Kamatayan", "O Allah, buhayin mo ako hangga't ang buhay ay mas mabuti para sa akin, at kunin mo ako kapag ang kamatayan ay mas mabuti para sa akin.", "Sa halip na hilingin ang kamatayan sa hirap.", "Ipinagbawal ng Propeta ﷺ ang pagnanais na mamatay at itinuro ito sa halip."),
        "dua_for_one_i_cursed" to DuaText("Para sa Isang Tao na Nasasaktan ako sa mga Salita", "O Allah, sinumang mananampalataya na aking ininsulto, gawin iyan na isang paraan ng paglapit sa Iyo para sa kanya sa Araw ng Muling Pagkabuhay.", "Para sa isang taong kinausap mo ng masama sa galit.", "Isang panalangin ng Propeta ﷺ."),
        "dua_praising_someone" to DuaText("Kapag Pinupuri ang Isang Tao", "Itinuturing kong ganito si ganito-at-ganito, at si Allah ang kanyang Tagapagtutuos, at hindi ko tinitiyak ang kadalisayan ng sinuman sa harap ng Allah.", "Kapag pinupuri ang isang tao, imbes na magpalabis.", "Itinuro ng Propeta ﷺ ang kagandahang-asal ng papuri."),
        "dua_being_praised" to DuaText("Kapag Ikaw ay Pinupuri", "O Allah, huwag mo akong ipagsusulit sa kanilang sinasabi, at patawarin mo ako sa hindi nila nalalaman.", "Nang marinig ang sarili na pinuri — ang pagsasanay ng isang Kasama (RA).", "Isang paraan upang maiwasan ang pagmamataas kapag pinupuri."),
        "dua_non_muslim_sneezes" to DuaText("Kapag ang isang Non-Muslim ay Bumahing", "Nawa'y gabayan ka ng Allah at ituwid ang iyong mga gawain.", "Kapag ang isang hindi Muslim ay bumahing at nagsabi ng 'Alhamdulillah'.", "Ang mga Hudyo ay bumahing malapit sa Propeta ﷺ umaasang sasabihin niya ang 'Yarhamukallah', at sasabihin niya ito."),
        "dua_reply_ahl_kitab_salam" to DuaText("Pagtugon sa Salam ng mga Tao ng Aklat", "At sa iyo.", "Kapag ang mga Tao ng Aklat ay bumati ng salam.", "Ang tagubilin ng Propeta ﷺ."),
        "dua_fasting_invited" to DuaText("Kapag Inanyayahan Habang Nag-aayuno", "nag-aayuno ako.", "Kapag inanyayahan habang nag-aayuno, o kapag may nakipag-away sa iyo.", "Kung ang taong nag-aayuno ay tumatanggap ng isang imbitasyon, dapat niyang ipagdasal ang host."),
        "dua_for_who_gave_drink" to DuaText("Para sa Kung Sinong Nagpakain sa Akin", "O Allah, pakainin mo ang nagpakain sa akin at painumin mo ang nagpainom sa akin.", "Para sa sinumang nagbibigay sa iyo ng pagkain o inumin.", "Ginawa ng Propeta ﷺ ang dua para sa al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Pagbati ng Eid", "Nawa'y tanggapin ng Allah (ang mabubuting gawa) mula sa amin at mula sa iyo.", "Sa isa't isa sa araw ng Eid - ang pagsasagawa ng mga marangal na Kasamahan (RA).", "Sinabi ito ng mga Kasama noong nagkita sila noong Eid."),
        "dua_wedding_night" to DuaText("Para sa Nobya Pagkatapos Nikah", "O Allah, hinihiling ko sa Iyo ang kanyang kabutihan at ang kabutihan ng kalikasan na nilikha Mo sa kanya, at nagpapakupkop ako sa Iyo mula sa kanyang kasamaan at ang kasamaan ng kalikasan na nilikha Mo sa kanya.", "Pagkatapos ng nikah, ilagay ang kamay sa noo ng asawa.", "Ang ﷺ na turo ng Propeta — pagpapala sa kasal."),
        "dua_istisqa_ibadak" to DuaText("Diligan ang Iyong mga Lingkod at Hayop", "O Allah, bigyan Mo ng tubig ang Iyong mga lingkod at ang Iyong mga hayop, ipalaganap ang Iyong awa at bigyan ng buhay ang Iyong patay na lupain.", "Paghingi ng ulan (istisqa).", "Ginawa ng Propeta ﷺ ang dua para sa ulan."),
        "dua_seeing_clouds" to DuaText("Nakikita ang Madilim na Ulap", "O Allah, ako ay nagpapakupkop sa Iyo mula sa kasamaan nito.", "Sa pagkakita ng maitim na ulap sa kalangitan; kung umuulan, sabihin ang 'Allahumma sayyiban nafi'a'.", "Nang makakita ng mga ulap, ang Propeta ﷺ ay umalis sa kanyang ginagawa at gawin itong dua."),
        "dua_jamarat" to DuaText("Pagbato sa Jamarat", "Si Allah ang Pinakamadakila.", "Sa bawat batong ibinabato.", "Ang Propeta ﷺ ay nagsabi ng takbir sa bawat maliit na bato, pagkatapos pagkatapos ng una at ikalawang jamrah ay humarap sa Qiblah at gumawa ng mahabang du'a."),
        "dua_rabbi_ainni" to DuaText("Panginoon, Tulungan Mo Ako at Huwag Laban sa Akin", "Panginoon ko, tulungan mo ako at huwag tulungan ang iba laban sa akin, bigyan mo ako ng tagumpay at huwag bigyan ang iba ng tagumpay laban sa akin, magplano para sa akin at huwag magplano laban sa akin, patnubayan mo ako at gawing madali para sa akin, at tulungan mo ako laban sa sinumang nagkasala sa akin.", "Isang komprehensibong dua ng Propeta ﷺ (pambungad na bahagi).", "Isang dua na nagtitipon ng bawat tulong sa relihiyon at sa mundong ito."),
        "dua_ati_nafsi_taqwaha" to DuaText("Ipagkaloob sa Aking Kaluluwa ang Taqwa Nito", "O Allah, ipagkaloob mo sa aking kaluluwa ang pagiging banal nito at dalisayin mo ito, sapagka't Ikaw ang pinakamahusay na naglilinis nito. Ikaw ang Tagapangalaga nito at ang Guro nito.", "Para sa reporma at paglilinis ng sarili.", "Ang Propeta ﷺ ay gumawa ng dalawang ito."),
        "dua_iqsim_lana_khashyatik" to DuaText("Bigyan Mo Kami ng Ganyan na Takot sa Iyo", "O Allah, bigyan mo kami ng sapat na takot sa Iyo upang pumagitna sa amin at pagsuway sa Iyo, sapat na pagsunod upang dalhin kami sa Iyong Paraiso, at sapat na katiyakan upang gawing madali para sa amin ang mga sakuna sa mundong ito. Nawa'y tamasahin namin ang aming pandinig, ang aming paningin at ang aming lakas hangga't pinananatili Mo kaming buhay, at pinalalagpasan Mo kami. Ipaghiganti namin ang mga nagkasala sa amin, tulungan kami laban sa aming mga kaaway, huwag hayaan ang aming kapahamakan sa aming relihiyon, huwag gawin ang mundong ito na aming pinakamalaking alalahanin o limitasyon ng aming kaalaman, at huwag itakda sa amin ang mga hindi magpapakita sa amin ng awa.", "Kapag bumangon mula sa isang pagtitipon - ang Propeta ﷺ ay bihirang bumangon nang hindi gumagawa ng dalawang ito.", "Isang komprehensibong panalangin para sa kabutihan ng relihiyon, sa mundong ito at sa Kabilang-Buhay."),
        "dua_infani_bima_allamtani" to DuaText("Makinabang Ako sa Itinuro Mo sa Akin", "O Allah, pakinabangan mo ako sa mga itinuro Mo sa akin, ituro mo sa akin kung ano ang mapapakinabangan ko, at dagdagan mo ako sa kaalaman.", "Habang naghahanap ng kaalaman o bago mag-aral.", "Isang dua para sa kapaki-pakinabang na kaalaman at pagkilos dito."),
    )
}
